import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { courses } from '../data/courses';
import paymentModal from '../components/paymentModal';
import Navbar from '../components/Navbar';

const Catalog = () => {
  const [search, setSearch] = useState('');
  const [category, setCategory] = useState('Tous');
  const [selectedCourse, setSelectedCourse] = useState(null);

  const categories = ['Tous', 'Réseau & Défense', 'Hacking Offensif'];

  const filtered = courses.filter(c =>
    (category === 'Tous' || c.category === category) &&
    c.title.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="bg-[#020617] min-h-screen text-white font-sans selection:bg-blue-500/30">
      <Navbar />

      <section className="max-w-6xl mx-auto px-8 pt-16 pb-8">
        <h1 className="text-3xl font-black mb-8">Catalogue des Formations</h1>

        <div className="flex flex-col md:flex-row gap-4 mb-10">
          <input
            type="text"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Rechercher un module..."
            className="flex-1 bg-slate-950 border border-slate-800 px-4 py-3 rounded-full text-sm focus:border-blue-500 outline-none transition-all"
          />
          <div className="flex gap-2 flex-wrap">
            {categories.map(cat => (
              <button
                key={cat}
                onClick={() => setCategory(cat)}
                className={`px-4 py-2 rounded-full text-[11px] font-mono uppercase tracking-wider border transition-all ${
                  category === cat
                    ? 'border-blue-500 bg-blue-500/10 text-blue-400'
                    : 'border-slate-800 text-slate-500 hover:border-slate-600'
                }`}
              >
                {cat}
              </button>
            ))}
          </div>
        </div>

        {filtered.length > 0 ? (
          <div className="grid md:grid-cols-3 gap-6">
            {filtered.map(course => (
              <div key={course.id} className="group p-8 bg-slate-950 border border-slate-900 rounded-2xl hover:border-blue-500/50 transition-all shadow-xl hover:-translate-y-2">
                <span className={`text-[10px] font-mono px-3 py-1 rounded-full ${course.isFree ? 'bg-emerald-500/10 text-emerald-400' : 'bg-blue-500/10 text-blue-400'}`}>
                  {course.isFree ? 'GRATUIT' : 'PREMIUM'}
                </span>
                <h3 className="text-lg font-bold mt-4 mb-2">{course.title}</h3>
                <p className="text-slate-500 text-xs mb-6 h-12">{course.description}</p>
                <div className="flex gap-3">
                  <Link to={`/course/${course.id}`} className="flex-1 text-center border border-slate-700 py-3 rounded-lg text-xs font-bold uppercase hover:bg-slate-900 transition">
                    Détails
                  </Link>
                  <button onClick={() => setSelectedCourse(course)} className="flex-1 bg-blue-600 py-3 rounded-lg text-xs font-bold uppercase hover:bg-blue-500 transition">
                    {course.isFree ? 'Accéder' : 'Débloquer'}
                  </button>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="border border-dashed border-slate-800 rounded-xl p-12 text-center text-slate-600 font-mono text-xs">
            Aucun cours trouvé.
          </div>
        )}
      </section>

      {selectedCourse && <paymentModal course={selectedCourse} onClose={() => setSelectedCourse(null)} />}
    </div>
  );
};
export default Catalog;
